shell_commands.command:
cd /testbed && patch -p1 <<'PATCH'
--- a/test/xchar-test.cc
+++ b/test/xchar-test.cc
@@ -440,6 +440,39 @@ TEST(locale_test, localized_double) {
   EXPECT_EQ(fmt::format(loc, "{:8L}", 1230.0), "   1~230");
 }

+TEST(locale_test, localized_float_alignment) {
+  auto loc = std::locale(std::locale::classic(), new special_grouping<char>());
+  EXPECT_EQ("              0.295", fmt::format(loc, "{:19.3Lf}", 0.295));
+  EXPECT_EQ("             -0.295", fmt::format(loc, "{:19.3Lf}", -0.295));
+  EXPECT_EQ("              1.295", fmt::format(loc, "{:19.3Lf}", 1.295));
+  EXPECT_EQ("           -119.921", fmt::format(loc, "{:19.3Lf}", -119.921));
+  EXPECT_EQ("          2,194.139", fmt::format(loc, "{:19.3Lf}", 2194.139));
+  EXPECT_EQ("            -57.639", fmt::format(loc, "{:19.3Lf}", -57.639));
+  EXPECT_EQ("             -5.980", fmt::format(loc, "{:19.3Lf}", -5.980));
+  EXPECT_EQ("             -2.119", fmt::format(loc, "{:19.3Lf}", -2.119));
+  EXPECT_EQ("   0.000", fmt::format(loc, "{:8.3Lf}", 0.0));
+  EXPECT_EQ("   0.030", fmt::format(loc, "{:8.3Lf}", 0.0295));
+  EXPECT_EQ("   0.295", fmt::format(loc, "{:8.3Lf}", 0.295f));
+  EXPECT_EQ("   0.295", fmt::format(loc, "{:8.3Lf}", 0.295L));
+  EXPECT_EQ("   1.234", fmt::format(loc, "{:8L}", 1.234));
+  EXPECT_EQ("0.295   ", fmt::format(loc, "{:<8.3Lf}", 0.295));
+  EXPECT_EQ(" 0.295  ", fmt::format(loc, "{:^8.3Lf}", 0.295));
+  EXPECT_EQ("0000.295", fmt::format(loc, "{:08.3Lf}", 0.295));
+  EXPECT_EQ("-000.295", fmt::format(loc, "{:08.3Lf}", -0.295));
+}
+
+TEST(locale_test, localized_wide_float_alignment) {
+  auto loc = std::locale(std::locale::classic(), new numpunct<wchar_t>());
+  EXPECT_EQ(L"              0?295", fmt::format(loc, L"{:19.3Lf}", 0.295));
+  EXPECT_EQ(L"             -0?295", fmt::format(loc, L"{:19.3Lf}", -0.295));
+  EXPECT_EQ(L"              1?295", fmt::format(loc, L"{:19.3Lf}", 1.295));
+  EXPECT_EQ(L"          2~194?139", fmt::format(loc, L"{:19.3Lf}", 2194.139));
+  EXPECT_EQ(L"   1?234", fmt::format(loc, L"{:8L}", 1.234));
+  EXPECT_EQ(L"0?295   ", fmt::format(loc, L"{:<8.3Lf}", 0.295));
+  EXPECT_EQ(L" 0?295  ", fmt::format(loc, L"{:^8.3Lf}", 0.295));
+  EXPECT_EQ(L"0000?295", fmt::format(loc, L"{:08.3Lf}", 0.295));
+}
+
